# tip: hints for the tools in this config (TIPS_FILE: "command<TAB>hint" lines, generated by tips.nix)
#   tip           one random tip
#   tip --all     search all tips in fzf; enter copies the command
#   tip --rofi    same in rofi (bound to Super+/)
#   tip --daily   one random tip, only on the first call of the day
show() { awk -F'\t' '{ printf "\033[1;34m%s\033[0m  %s\n", $1, $2 }'; }
copy() { cut -f1 | tr -d '\n' | xclip -selection clipboard; }

case "${1:-}" in
  --all)
    sel=$(fzf --delimiter='\t' --with-nth=1,2 --layout=reverse --prompt='tips> ' \
      --header='enter: copy command' <"$TIPS_FILE") || exit 0
    copy <<<"$sel"
    cut -f1 <<<"$sel"
    ;;
  --rofi)
    sel=$(rofi -dmenu -i -p tips -display-columns 1,2 -display-column-separator '\t' \
      <"$TIPS_FILE") || exit 0
    copy <<<"$sel"
    ;;
  --daily)
    stamp="${XDG_STATE_HOME:-$HOME/.local/state}/tip-daily"
    [ "$(cat "$stamp" 2>/dev/null)" != "$(date +%F)" ] || exit 0
    mkdir -p "$(dirname "$stamp")" && date +%F >"$stamp"
    printf 'tip: '
    shuf -n1 "$TIPS_FILE" | show
    ;;
  *) shuf -n1 "$TIPS_FILE" | show ;;
esac
